import {
  coordinates,
  isNamedPitch,
  isPitch,
  NamedPitch,
  Pitch,
  pitch,
  PitchCoordinates,
} from "@tonaljs/pitch";

const fillStr = (s: string, n: number) => Array(Math.abs(n) + 1).join(s);

export type NoteWithOctave = string;
export type PcName = string;
export type NoteName = NoteWithOctave | PcName;
export type NoteLiteral = NoteName | Pitch | NamedPitch;

export interface Note extends Pitch, NamedPitch {
  readonly empty: boolean;
  readonly name: NoteName;
  readonly letter: string;
  readonly acc: string;
  readonly ups: number;
  readonly pc: PcName;
  readonly chroma: number;
  readonly height: number;
  readonly coord: PitchCoordinates;
  readonly midi: number | null;
  readonly freq: number | null;
}

export type NoteType = Note;

const NoNote: Note = Object.freeze({
  empty: true,
  name: "",
  letter: "",
  acc: "",
  ups: NaN,
  pc: "",
  step: NaN,
  alt: NaN,
  chroma: NaN,
  height: NaN,
  coord: [] as unknown as PitchCoordinates,
  midi: null,
  freq: null,
});

const cache: Map<NoteLiteral | undefined, Note> = new Map();

export const stepToLetter = (step: number) => "CDEFGAB".charAt(step);
export const altToAcc = (alt: number): string =>
  alt < 0 ? fillStr("b", -alt) : fillStr("#", alt);
export const accToAlt = (acc: string): number =>
  acc[0] === "b" ? -acc.length : acc.length;
export const upsToArrows = (ups: number): string =>
  ups < 0 ? fillStr("↓", -ups) : fillStr("↑", ups);

export const arrowsToUps = (arrows: string): number => {
  let ups = 0;
  for (const ch of arrows) {
    if (ch === "↑" || ch === "^") ups += 1;
    else if (ch === "↓" || ch === "v") ups -= 1;
  }
  return ups;
};

/**
 * Given a note literal (a note name or a note object), returns the Note object
 * @example
 * note('Bb4') // => { name: "Bb4", midi: 70, chroma: 10, ... }
 */
export function note(src: NoteLiteral): Note {
  const stringSrc = JSON.stringify(src);

  const cached = cache.get(stringSrc);
  if (cached) {
    return cached;
  }

  const value =
    typeof src === "string"
      ? parse(src)
      : isPitch(src)
        ? note(pitchName(src))
        : isNamedPitch(src)
          ? note(src.name)
          : NoNote;
  // Only valid notes are cached, so arbitrary input can't grow the cache
  if (!value.empty) cache.set(stringSrc, value);
  return value;
}

type NoteTokens = [string, string, string, string];

const REGEX = /^([a-gA-G]?)(#{1,}|b{1,}|x{1,}|)(-?\d*)\s*(.*)$/;

/**
 * @private
 */
export function tokenizeNote(str: string): NoteTokens {
  const m = REGEX.exec(str) as string[];
  return m
    ? [m[1].toUpperCase(), m[2].replace(/x/g, "##"), m[3], m[4]]
    : ["", "", "", ""];
}

// ups and downs go before the note ("^C") or after the accidentals ("C↑")
const UPS_REGEX = /^([\^v↑↓]*)([a-gA-G](?:#+|b+|x+)?)([↑↓]*)(?![#bx])(.*)$/;

/**
 * @private
 */
export function tokenizeUps(str: string): [number, string] {
  const m = UPS_REGEX.exec(str);
  if (!m || (m[1] === "" && m[3] === "")) {
    return [0, str];
  }
  return [arrowsToUps(m[1] + m[3]), m[2] + m[4]];
}

/**
 * @private
 */
export function coordToNote(noteCoord: PitchCoordinates, ups = 0): Note {
  const p = pitch(noteCoord);
  return note(ups ? { ...p, ups } : p) as Note;
}

const mod = (n: number, m: number) => ((n % m) + m) % m;

const SEMI = [0, 2, 4, 5, 7, 9, 11];
function parse(fullName: NoteName): Note {
  const [ups, noteName] = tokenizeUps(fullName);
  const tokens = tokenizeNote(noteName);
  if (tokens[0] === "" || tokens[3] !== "") {
    return NoNote;
  }

  const letter = tokens[0];
  const acc = tokens[1];
  const octStr = tokens[2];

  const step = (letter.charCodeAt(0) + 3) % 7;
  const alt = accToAlt(acc);
  const oct = octStr.length ? +octStr : undefined;
  const coord = coordinates({ step, alt, oct });

  const arrows = upsToArrows(ups);
  const name = letter + acc + arrows + octStr;
  const pc = letter + acc + arrows;
  const chroma = mod(SEMI[step] + alt + ups, 12);
  const height =
    oct === undefined
      ? mod(SEMI[step] + alt + ups, 12) - 12 * 99
      : SEMI[step] + alt + ups + 12 * (oct + 1);
  const midi = height >= 0 && height <= 127 ? height : null;
  const freq = oct === undefined ? null : Math.pow(2, (height - 69) / 12) * 440;

  return {
    empty: false,
    acc,
    alt,
    chroma,
    coord,
    freq,
    height,
    letter,
    midi,
    name,
    oct,
    pc,
    step,
    ups,
  };
}

function pitchName(props: Pitch): NoteName {
  const { step, alt, oct, ups = 0 } = props;
  const letter = stepToLetter(step);
  if (!letter) {
    return "";
  }

  const pc = letter + altToAcc(alt) + upsToArrows(ups);
  return oct || oct === 0 ? pc + oct : pc;
}
